	(350, NULL, 'created', 'whatsapp_templates', 'App\Models\WhatsappTemplate', 1, NULL, '{"id": 1, "body": "Hola {{nombre}}, le recordamos que tiene un saldo pendiente de S/ {{saldo}} con vencimiento {{fecha_vencimiento}}. Responda a este mensaje si desea ayuda con su pago.", "name": "recordatorio_pago", "uuid": "d5ee7acd-b047-42a8-8c38-ed218b67a730", "status": "approved", "category": "utility", "language": "es", "created_at": "2026-07-21 21:24:56"}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
	(351, NULL, 'created', 'whatsapp_templates', 'App\Models\WhatsappTemplate', 2, NULL, '{"id": 2, "body": "Hola {{nombre}}, confirmamos su compromiso de pago de S/ {{saldo}} para el {{fecha_compromiso}}. Gracias.", "name": "confirmacion_compromiso", "uuid": "d5f0d089-4868-4fe9-a9b1-64da72e8a935", "status": "approved", "category": "utility", "language": "es", "created_at": "2026-07-21 21:24:56"}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
	(352, NULL, 'created', 'message_templates', 'App\Models\MessageTemplate', 1, NULL, '{"id": 1, "body": "Hola {{nombre}}, le informamos que mantiene un saldo pendiente de {{saldo}} soles con vencimiento el {{fecha_vencimiento}}. Presione 1 para confirmar que recibió este mensaje.", "name": "Aviso de vencimiento TTS", "type": "tts", "uuid": "5b289992-ef20-41d7-af35-1d93ae46750f", "voice": "Polly.Mia", "language": "es-MX", "created_at": "2026-07-21 21:24:56"}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
	(353, NULL, 'created', 'call_prompts', 'App\Models\CallPrompt', 1, NULL, '{"id": 1, "name": "Agente de cobranzas estándar", "type": "collections", "uuid": "37a3c863-62e8-4b71-b91b-1705dc06045c", "status": "published", "created_at": "2026-07-21 21:24:56", "created_by": 1, "description": "Agente conversacional para recordatorio de deuda y registro de compromisos de pago."}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
	(354, NULL, 'created', 'prompt_versions', 'App\Models\PromptVersion', 1, NULL, '{"id": 1, "faq": "[{\"q\":\"d\\u00f3nde puedo pagar\",\"a\":\"Puede pagar en caja de la instituci\\u00f3n, por transferencia al BCP o desde la plataforma virtual con su c\\u00f3digo de alumno.\"},{\"q\":\"puedo pagar en partes\",\"a\":\"S\\u00ed, puede solicitar un fraccionamiento en el \\u00e1rea de finanzas. Un asesor puede ayudarle con el tr\\u00e1mite.\"},{\"q\":\"ya pagu\\u00e9\",\"a\":\"Si ya realiz\\u00f3 el pago, este puede tardar hasta 48 horas en reflejarse. Puede enviar su comprobante por WhatsApp.\"}]", "uuid": "47765dd8-73a2-4c67-ac30-9d32baadecf6", "status": "published", "version": 1, "variables": "[\"nombre\",\"apellido\",\"saldo\",\"fecha_vencimiento\"]", "created_at": "2026-07-21 21:24:56", "created_by": 1, "guardrails": "{\"forbidden_data\":[\"DNI completo\",\"datos de otros alumnos\",\"informaci\\u00f3n interna\"],\"security_rules\":[\"No ofrecer descuentos ni condonaciones\",\"No amenazar ni presionar\",\"M\\u00e1ximo 5 minutos de conversaci\\u00f3n\"]}", "instructions": "1. Saluda y verifica que hablas con el titular.\n2. Solo tras validar identidad, informa la deuda usando consultar_deuda.\n3. Busca un compromiso de pago con fecha concreta.\n4. Si pide hablar con una persona, usa solicitar_asesor.\n5. Si pide información por escrito, usa enviar_whatsapp.\n6. Cierra siempre con finalizar_llamada.", "published_at": "2026-07-21 21:24:56", "enabled_tools": "[\"obtener_contacto\",\"validar_identidad\",\"consultar_deuda\",\"registrar_acuerdo\",\"registrar_observacion\",\"programar_seguimiento\",\"enviar_whatsapp\",\"solicitar_asesor\",\"finalizar_llamada\",\"consultar_preguntas_frecuentes\"]", "system_prompt": "Eres una asistente virtual del área de cobranzas de una institución educativa. Eres amable, empática y profesional. Tu objetivo es informar al titular sobre su deuda pendiente y lograr un compromiso de pago concreto (fecha y monto). Hablas en español peruano formal pero cercano.", "call_prompt_id": 1, "farewell_message": "Gracias por su tiempo. Que tenga un excelente día.", "greeting_message": "Buenos días, le saluda la asistente virtual del área de cobranzas. ¿Tengo el gusto con {{nombre_completo}}?", "extraction_fields": "[\"fecha_compromiso\",\"monto_comprometido\",\"sentimiento\"]", "max_duration_seconds": 300}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
	(355, NULL, 'created', 'campaigns', 'App\Models\Campaign', 1, NULL, '{"id": 1, "name": "Recordatorio de vencimiento julio", "type": "tts", "uuid": "eb10472f-dd54-45ae-a9dc-fee2452da4d0", "status": "draft", "language": "es-MX", "priority": 5, "timezone": "America/Lima", "created_at": "2026-07-21 21:24:56", "created_by": 1, "description": "Itaque molestiae magni consequatur nihil quam.", "tts_message": "Hola {{nombre}}, le informamos que mantiene un saldo pendiente de {{saldo}} soles con vencimiento el {{fecha_vencimiento}}.", "allowed_days": "[1,2,3,4,5]", "allowed_from": "08:00", "dtmf_options": "{\"1\":{\"action\":\"confirm\"},\"2\":{\"action\":\"send_whatsapp\",\"template_uuid\":\"d5ee7acd-b047-42a8-8c38-ed218b67a730\"},\"3\":{\"action\":\"transfer_advisor\"}}", "max_attempts": 3, "record_calls": true, "allowed_until": "20:00", "retry_minutes": 120, "supervisor_id": 2, "segment_filters": "{\"min_debt\":100,\"debt_status\":[\"pending\",\"overdue\"]}", "post_call_actions": "{\"send_whatsapp_after_answer\":false}", "max_concurrent_calls": 5}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
	(356, NULL, 'created', 'campaigns', 'App\Models\Campaign', 2, NULL, '{"id": 2, "name": "Gestión IA mora mayor a 30 días", "type": "ai_conversational", "uuid": "886a8bad-f1ca-46bc-8243-88d0b0e62b33", "status": "draft", "language": "es-MX", "priority": 5, "timezone": "America/Lima", "created_at": "2026-07-21 21:24:56", "created_by": 1, "description": "Molestiae laborum eaque necessitatibus ipsum facilis labore.", "tts_message": "Hola {{nombre}}, le informamos que mantiene un saldo pendiente de {{saldo}} soles con vencimiento el {{fecha_vencimiento}}.", "allowed_days": "[1,2,3,4,5]", "allowed_from": "08:00", "max_attempts": 3, "record_calls": true, "allowed_until": "20:00", "retry_minutes": 120, "supervisor_id": 2, "segment_filters": "{\"min_days_overdue\":30,\"debt_status\":[\"overdue\"]}", "greeting_message": "Buenos días, le saluda la asistente virtual del área de cobranzas.", "prompt_version_id": 1, "max_concurrent_calls": 5}', '127.0.0.1', 'Symfony', NULL, '2026-07-21 21:24:56'),
